class ApplyCTFThread(QtCore.QThread):

    progress = QtCore.pyqtSignal(int)

    finished_label = QtCore.pyqtSignal()

    def __init__(self, msgbox, dir_to_save, cancel, create_copy, overwrite):
       
        QtCore.QThread.__init__(self)

        self.msgbox = msgbox

        self.dir_to_save = dir_to_save

        self.cancel = cancel

        self.create_copy = create_copy

        self.overwrite = overwrite

        self.data_store = DataStore()

        self.applyCTF = CTFPage(self.data_store)

        self.applyCTF.progress.connect(self.send_progress)

    def run(self):
        
        self.applyCTF.apply_ctf_to_dir(self.msgbox, self.dir_to_save, self.cancel, self.create_copy, self.overwrite)

        self.finished_label.emit()

    def send_progress(self, value):
        
        self.progress.emit(value)

